import React from 'react';
import {createNativeStackNavigator} from '@react-navigation/native-stack';
import SmartTestHomeScreen from '../screens/SmartTestHomeScreen';
import FreeTestScreen from '../screens/FreeTestScreen';
import StudentReportScreen from '../screens/StudentReportScreen';
import ListExamResultScreen from '../screens/dashboard/ListExamResultScreen';
import StudentGuideScreen from '../screens/StudentGuideScreen';
import ClassInfoScreen from '../screens/ClassInfoScreen';
import PrivacyScreen from '../screens/PrivacyScreen';
import TermsScreen from '../screens/TermsScreen';
import MyStudyBookScreen from '../screens/MyStudyBookScreen';
import StudyBookContentScreen from '../screens/StudyBookContentScreen';
import {useTheme} from 'react-native-paper';

export type MainStackParamList = {
  SmartTestHomeScreen: undefined;
  FreeTestScreen: undefined;
  StudentReportScreen: undefined;
  ListExamResultScreen: {maDeThi: string} | undefined;
  StudentGuideScreen: undefined;
  ClassInfoScreen: undefined;
  PrivacyScreen: undefined;
  TermsScreen: undefined;
  MyStudyBookScreen: undefined;
  StudyBookContentScreen: undefined;
};

const Main = createNativeStackNavigator<MainStackParamList>();

const MainNavigator = () => {
  const theme = useTheme();
  return (
    <Main.Navigator
      screenOptions={{
        statusBarColor: theme.colors.primaryContainer,
        statusBarStyle: 'dark',
        headerShown: false,
      }}>
      <Main.Screen name="SmartTestHomeScreen" component={SmartTestHomeScreen} />
      <Main.Screen name="MyStudyBookScreen" component={MyStudyBookScreen} />
      <Main.Screen
        name="StudyBookContentScreen"
        component={StudyBookContentScreen}
      />
      <Main.Screen name="FreeTestScreen" component={FreeTestScreen} />
      <Main.Screen name="StudentReportScreen" component={StudentReportScreen} />
      <Main.Screen name="StudentGuideScreen" component={StudentGuideScreen} />
      <Main.Screen name="ClassInfoScreen" component={ClassInfoScreen} />
      <Main.Screen name="PrivacyScreen" component={PrivacyScreen} />
      <Main.Screen name="TermsScreen" component={TermsScreen} />
      <Main.Screen
        name="ListExamResultScreen"
        component={ListExamResultScreen}
      />
    </Main.Navigator>
  );
};

export default MainNavigator;
