/* eslint-disable react-native/no-inline-styles */
import React from 'react';
import {StyleSheet, TouchableOpacity, View} from 'react-native';
import {Button, Text, TextInput, useTheme} from 'react-native-paper';
import {useAuthStore, buildLink} from '@smarttestpro/smart-common';
import MIcon from 'react-native-vector-icons/MaterialIcons';
import {DoExamAnimation} from '../lotties';

const FreeTestScreen = ({navigation}: any) => {
  const theme = useTheme();
  const [maDeThi, setMaDeThi] = React.useState('abcd1234');
  const {accessToken, refreshToken} = useAuthStore();
  const enterFreeExam = () => {
    const baseUrl = 'https://smarttest.pro';
    const url = `/${buildLink(
      'test-taking/entrance-exam/:id/079dd2ea-dc4c-4faa-b93e-8eb16935c98f',
      {
        id: maDeThi,
      },
    )}`;
    const uri = `${baseUrl}/thanh-vien/dang-nhap?return_to=${encodeURI(
      url,
    )}&accessToken=${encodeURI(accessToken || '')}&refreshToken=${encodeURI(
      refreshToken || '',
    )}`;
    navigation.push('TestExamWebScreen', {
      uri,
    });
  };

  return (
    <View style={styles.container}>
      <View
        className={`h-10 bg-[${theme.colors.primaryContainer}] flex-row items-center px-2`}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <View className="px-1 h-10 justify-center">
            <MIcon name="arrow-back" size={24} />
          </View>
        </TouchableOpacity>
        <View className="flex-1 items-center mr-2">
          <Text className="text-lg font-bold text-gray-800">Thi tự do</Text>
        </View>
      </View>
      <View className="flex-col flex-1">
        <View className="p-4 flex-1 justify-center gap-y-2">
          <View className="flex-row justify-center">
            <DoExamAnimation />
          </View>
          <Text className="text-center" variant="titleMedium">
            Ghi chú
          </Text>
          <Text className="">
            1. Mã đề thi sẽ được giáo viên gửi cho từng học sinh. Để thay đổi mã
            đề, bấm vào "abcd123" để nhập mã đề nhận được.
          </Text>
          <Text className="">
            2. Để trải nghiệm bạn có thể sử dụng mã đề thi mẫu sau : abcd1234.
          </Text>
        </View>
        <View className="flex-row bg-white justify-center p-4 gap-x-2">
          <TextInput
            className="flex-1 bg-white"
            label="Nhập mã đề thi"
            value={maDeThi}
            mode="outlined"
            onChangeText={text => setMaDeThi(text)}
          />
          <View className="justify-center">
            <Button
              contentStyle={{flexDirection: 'row-reverse'}}
              mode="contained"
              onPress={() => enterFreeExam()}
              className="mt-2"
              icon="play">
              <Text className="text-white">Vào thi</Text>
            </Button>
          </View>
        </View>
      </View>
    </View>
  );
};
const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'white',
  },
});

export default FreeTestScreen;
