/* eslint-disable react-native/no-inline-styles */
import React, {useCallback, useEffect, useState} from 'react';
import {
  StyleSheet,
  View,
  FlatList,
  RefreshControl,
  Image,
  TouchableOpacity,
} from 'react-native';
import {ActivityIndicator, Text, useTheme} from 'react-native-paper';
import {getMyStudyBook} from '../api/dashboard-api';
import {BookLoverSvg} from '../assets/imgs/book-lover-svg';
import MIcon from 'react-native-vector-icons/MaterialIcons';
import {FormatQuoteSvg} from '../assets/imgs/format-quote-svg';

const MyStudyBookScreen = ({navigation}: any) => {
  const theme = useTheme();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  // Function to fetch data
  const fetchData = useCallback(
    async (isRefreshing = false) => {
      if (loading) {
        return;
      }

      setLoading(true);
      try {
        const response = await getMyStudyBook();
        setData(response.data);
        console.log(response.data, 'response.data');
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
        if (isRefreshing) {
          setRefreshing(false);
        }
      }
    },
    [loading],
  );

  // Load data on mount
  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Handle pull-to-refresh
  const onRefresh = useCallback(() => {
    setRefreshing(true);
    fetchData(true); // Reload data
  }, [fetchData]);

  const renderHeader = () => (
    <View className={`flex-col bg-[${theme.colors.primaryContainer}]`}>
      <View className="flex-row pb-4 px-4 gap-x-2">
        <View>
          <BookLoverSvg width={130} height={130} />
        </View>
        <View className="pt-8">
          <View className="flex-row justify-center">
            <FormatQuoteSvg className="mb-1" />
            <View className="flex-col">
              <Text className="text-lg text-black font-semibold">
                Thách thức giới hạn
              </Text>
              <View className="flex-row">
                <Text className="text-lg text-black font-semibold">
                  tiếp cận tri thức!
                </Text>
                <FormatQuoteSvg className="mb-1" />
              </View>
              <Text className="pt-2 text-right text-sm italic">Yolo thôi.</Text>
            </View>
          </View>
        </View>
      </View>
    </View>
  );

  return (
    <View style={styles.container}>
      <View
        className={`h-10 bg-[${theme.colors.primaryContainer}] flex-row items-center px-2`}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <View className="px-1 h-10 justify-center">
            <MIcon name="arrow-back" size={24} />
          </View>
        </TouchableOpacity>
        <View className="flex-1 items-center mr-2">
          <Text className="text-lg font-bold text-gray-800">
            Tài liệu của tôi {data.length ? `(${data.length})` : ''}
          </Text>
        </View>
      </View>
      {loading && !refreshing ? (
        <ActivityIndicator size="large" color="#0000ff" />
      ) : (
        <FlatList
          data={data}
          ListHeaderComponent={renderHeader}
          keyExtractor={(item: any) => item.id}
          renderItem={({item}: any) => (
            <View className="px-3">
              <View className="flex-row py-3 border-b border-gray-200">
                <TouchableOpacity
                  onPress={() => {
                    navigation.push('StudyBookContentScreen');
                  }}>
                  <View>
                    <Image
                      style={{
                        width: 80,
                        height: 100,
                        // borderWidth: 1,
                        borderRadius: 8,
                      }}
                      source={{uri: item.moTa}}
                      resizeMode="cover"
                    />
                  </View>
                </TouchableOpacity>

                <View className="flex-col flex-1 ml-2">
                  <View className="mt-2">
                    <Text variant="titleSmall">{item.tenSach}</Text>
                  </View>
                  <View className={'h-0.5 bg-orange-300 rounded w-10 mt-1'} />
                  <View className="flex-row items-center gap-1 mt-1">
                    <MIcon name="corporate-fare" size={16} />
                    <Text>{item.nhaXuatBan}</Text>
                  </View>
                </View>
              </View>
            </View>
          )}
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
        />
      )}
    </View>
  );
};
const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
});

export default MyStudyBookScreen;
